    <section aria-label="New artifact" className="rounded-xl border border-border bg-card p-4">
      <ArtifactPrompt key={prompt} defaultValue={prompt?.slice(0, 4000)} placeholder="Describe what to build, e.g. “What if my rent goes up €300 — how does my monthly budget look?”" />
    </section>
    <ArtifactBuilds builds={builds} />
    <section aria-label="Examples" className="grid gap-3">
      <h2 className="text-sm font-medium text-muted-foreground">Start from an example</h2>
      <ul className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{artifactExamples.map(example => <li key={example.title}>
        <Link href={`/ai/artifacts?prompt=${encodeURIComponent(example.prompt)}`} scroll={false} className="block h-full rounded-xl border border-border bg-card p-4 hover:bg-muted">
          <span className="block font-medium">{example.title}</span>
          <span className="mt-1 block text-xs text-muted-foreground">{example.summary}</span>
        </Link></li>)}</ul>
    </section>
    {error ? <p role="alert">Could not load artifacts.</p> : !data.length ? <p className="text-sm text-muted-foreground">No artifacts yet.</p> :
      <ul className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{data.map(artifact => <li key={artifact.id} className="relative flex h-full flex-col overflow-hidden rounded-xl border border-border bg-card hover:bg-muted">
        <ArtifactThumbnail src={`/ai/artifacts/${artifact.id}/frame`} title={artifact.title} />
        <div className="flex items-start gap-2 border-t border-border p-4">
          <div className="min-w-0 flex-1">
            {/* The stretched link makes the whole card clickable while the delete button stays its own control. */}
            <Link href={`/ai/artifacts/${artifact.id}`} className="block font-medium after:absolute after:inset-0 after:rounded-xl">{artifact.title}</Link>
            {/* The original request says what the artifact is for. */}
            {artifact.artifact_versions[0]?.prompt && <span className="mt-1 line-clamp-2 text-sm text-muted-foreground">{artifact.artifact_versions[0].prompt}</span>}
            <span className="mt-1 block text-xs text-muted-foreground">Updated {date.format(new Date(artifact.updated_at))}</span>
          </div>
          <DeleteArtifactButton id={artifact.id} title={artifact.title} label="" className="relative z-10 -m-1 p-1" />
        </div></li>)}</ul>}
  </main>;
}
"use server";

import { redirect } from "next/navigation";
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";

/** Soft delete: the artifact leaves the gallery, its versions are kept. */
export async function deleteArtifact(id: string) {
  const artifactId = z.uuid().parse(id);
  const { supabase, workspace } = await requireWorkspace();
  const { error } = await supabase.from("artifacts").update({ deleted_at: new Date().toISOString() }).eq("workspace_id", workspace.id).eq("id", artifactId);
  if (error) throw error;
  redirect("/ai/artifacts");
}
"use client";

import { Trash2 } from "lucide-react";
import { deleteArtifact } from "./actions";

/** Asks first, like deleting a chat; the artifact is soft-deleted and its versions are kept. */
export function DeleteArtifactButton({ id, title, className = "", label = "Delete artifact" }: { id: string; title: string; className?: string; label?: string }) {
  return <form action={deleteArtifact.bind(null, id)} className={className}
    onSubmit={event => { if (!window.confirm(`Delete “${title}”? It leaves your artifacts and Home. Its versions are kept.`)) event.preventDefault(); }}>
    <button type="submit" aria-label={label ? undefined : `Delete ${title}`} className="inline-flex items-center gap-1 rounded-lg text-xs text-muted-foreground hover:text-danger">
      <Trash2 className="size-3.5" aria-hidden="true" />{label}</button>
  </form>;
}

