"use client";

import { useState } from "react";

type Series = { name: string; values: (number | null)[]; color?: string };
export type CardChartProps = { type: "line" | "area" | "bar" | "hbar" | "donut" | "sparkline"; labels: string[]; series: Series[]; stacked?: boolean; axis?: boolean; currency?: string; height?: number; className?: string; style?: React.CSSProperties };

// The app's own chart colours, in order, for series that don't pick one.
const PALETTE = ["var(--color-brand)", "var(--color-ai)", "var(--color-chart-out)", "var(--color-warning)", "var(--color-chart-input)", "var(--color-success)", "var(--color-danger)", "var(--color-muted-foreground)"];
const W = 600;

function format(value: number | null | undefined, currency?: string) {
  if (value === null || value === undefined) return "–";
  return currency ? new Intl.NumberFormat(undefined, { style: "currency", currency, maximumFractionDigits: Math.abs(value) >= 1000 ? 0 : 2 }).format(value)
    : new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 }).format(value);
}

/** Charts drawn as SVG by the app from the card's numbers; the card never passes code or HTML to a chart. */
export function CardChart({ type, labels, series, stacked, axis, currency, height, className, style }: CardChartProps) {
  const [active, setActive] = useState<number | null>(null);
  const colors = series.map((item, index) => item.color ?? PALETTE[index % PALETTE.length]);
  const count = Math.max(labels.length, ...series.map(item => item.values.length));
  const tooltip = active !== null && <div role="status" className="pointer-events-none absolute top-0 z-10 rounded-lg border border-border bg-card px-2.5 py-1.5 text-xs shadow-lg"
    style={{ left: `clamp(0px, calc(${((active + 0.5) / count) * 100}% - 4rem), calc(100% - 8rem))` }}>
    {labels[active] && <p className="text-muted-foreground">{labels[active]}</p>}
    {series.map((item, index) => <p key={item.name} className="flex items-center gap-1.5 whitespace-nowrap font-mono"><span className="size-2 rounded-full" style={{ background: colors[index] }} />{series.length > 1 && `${item.name} `}{format(item.values[active], currency)}</p>)}
  </div>;

  if (type === "donut") {
    const values = series[0].values.map(value => Math.max(0, value ?? 0));
    const total = values.reduce((sum, value) => sum + value, 0) || 1;
    let offset = 0;
    const size = height ?? 140;
    return <div className={`relative flex items-center gap-4 ${className ?? ""}`} style={style} onPointerLeave={() => setActive(null)}>
      <svg viewBox="0 0 42 42" width={size} height={size} role="img" aria-label={series[0].name} className="shrink-0 -rotate-90">
        <circle cx="21" cy="21" r="15.915" fill="none" stroke="var(--color-muted)" strokeWidth="6" />
        {values.map((value, index) => {
          const share = (value / total) * 100, dash = `${share} ${100 - share}`, start = offset;
          offset += share;
          return <circle key={index} cx="21" cy="21" r="15.915" fill="none" stroke={PALETTE[index % PALETTE.length]} strokeWidth={active === index ? 7.5 : 6}
            strokeDasharray={dash} strokeDashoffset={-start} onPointerEnter={() => setActive(index)} className="transition-[stroke-width]" />;
        })}
      </svg>
      <ul className="min-w-0 flex-1 space-y-1 text-xs">{values.map((value, index) => <li key={index} onPointerEnter={() => setActive(index)} className={`flex items-center gap-2 ${active === null || active === index ? "" : "opacity-50"}`}>
        <span className="size-2 shrink-0 rounded-full" style={{ background: PALETTE[index % PALETTE.length] }} /><span className="min-w-0 flex-1 truncate">{labels[index]}</span><span className="font-mono">{format(value, currency)}</span></li>)}</ul>
    </div>;
  }

  if (type === "hbar") {
    const values = series[0].values;
    const max = Math.max(...values.map(value => Math.abs(value ?? 0)), 1);
    return <ul className={`space-y-2 text-sm ${className ?? ""}`} style={style}>{values.map((value, index) => <li key={index}>
      <div className="flex justify-between gap-3"><span className="truncate">{labels[index]}</span><span className="shrink-0 font-mono text-xs">{format(value, currency)}</span></div>
      <div className="mt-1 h-1.5 rounded-full bg-muted"><div className="h-full rounded-full" style={{ width: `${(Math.abs(value ?? 0) / max) * 100}%`, background: colors[0] }} /></div>
    </li>)}</ul>;
  }

  const h = height ?? (type === "sparkline" ? 40 : 140);
  const totals = Array.from({ length: count }, (_, index) => series.reduce((sum, item) => sum + Math.max(0, item.values[index] ?? 0), 0));
  const all = stacked && type === "bar" ? totals : series.flatMap(item => item.values.filter((value): value is number => value !== null));
  const min = type === "bar" ? Math.min(0, ...all) : Math.min(...all), max = Math.max(...all, min + 1);
  const y = (value: number) => h - 2 - ((value - min) / (max - min)) * (h - 4);
  const x = (index: number) => count === 1 ? W / 2 : (index / (count - 1)) * W;
  const band = W / Math.max(count, 1);
  const pick = (event: React.PointerEvent<HTMLDivElement>) => { const rect = event.currentTarget.getBoundingClientRect(); setActive(Math.max(0, Math.min(count - 1, Math.floor(((event.clientX - rect.left) / rect.width) * count)))); };
  return <div className={className} style={style}>
    <div className="relative" onPointerMove={type === "sparkline" ? undefined : pick} onPointerLeave={() => setActive(null)}>
      <svg viewBox={`0 0 ${W} ${h}`} preserveAspectRatio="none" role="img" aria-label={series.map(item => item.name).join(", ")} className="block w-full overflow-visible" style={{ height: h }}>
        {type === "bar" ? series.map((item, seriesIndex) => item.values.map((value, index) => {
          if (value === null) return null;
          const below = stacked ? series.slice(0, seriesIndex).reduce((sum, other) => sum + Math.max(0, other.values[index] ?? 0), 0) : 0;
          const width = stacked ? band * 0.62 : (band * 0.62) / series.length;
          const left = index * band + band * 0.19 + (stacked ? 0 : seriesIndex * width);
          const top = y(below + Math.max(0, value)), bottom = y(below + Math.min(0, value));
          return <rect key={`${seriesIndex}-${index}`} x={left} y={top} width={width} height={Math.max(1, bottom - top)} rx={2} fill={colors[seriesIndex]} opacity={active === null || active === index ? 1 : 0.45} />;
        })) : series.map((item, seriesIndex) => {
          const points = item.values.map((value, index) => value === null ? null : `${x(index).toFixed(1)},${y(value).toFixed(1)}`).filter(Boolean).join(" ");
          return <g key={item.name}>
            {type === "area" && <polygon points={`${x(0)},${h} ${points} ${x(item.values.length - 1)},${h}`} fill={colors[seriesIndex]} opacity={0.15} />}
            <polyline points={points} fill="none" stroke={colors[seriesIndex]} strokeWidth={2} strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />
          </g>;
        })}
        {active !== null && type !== "bar" && <line x1={x(active)} x2={x(active)} y1={0} y2={h} stroke="var(--color-muted-foreground)" strokeOpacity={0.5} strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />}
      </svg>
      {tooltip}
    </div>
    {axis !== false && type !== "sparkline" && labels.length > 1 && <p className="mt-1 flex justify-between font-mono text-[10px] text-muted-foreground"><span>{labels[0]}</span>{labels.length > 2 && <span>{labels[Math.floor((labels.length - 1) / 2)]}</span>}<span>{labels.at(-1)}</span></p>}
  </div>;
}

/** Home card sizes: grid columns of the six-column Home grid at desktop width, and the body area a card designs for. */
export const CARD_SIZES = {
  S: { label: "S", columns: 2, span: "lg:col-span-2", width: 340 },
  M: { label: "M", columns: 3, span: "lg:col-span-3", width: 520 },
  L: { label: "L", columns: 4, span: "lg:col-span-4", width: 700 },
  XL: { label: "XL", columns: 6, span: "lg:col-span-6", width: 1080 },
} as const;
export type CardSize = keyof typeof CARD_SIZES;
export const CARD_SIZE_KEYS = Object.keys(CARD_SIZES) as CardSize[];
/** Every card has the same fixed height, so Home rows line up and nothing scrolls. */
export const CARD_HEIGHT = 300;
/** Height left for the card's own content under the title row. */
export const CARD_BODY_HEIGHT = 236;
export const isCardSize = (value: unknown): value is CardSize => typeof value === "string" && Object.hasOwn(CARD_SIZES, value);

"use client";

import { createContext, createElement, Fragment, useContext, useState, useTransition, type ReactNode } from "react";
import Link from "next/link";
import { formatMoney } from "@/lib/finance/format";
import type { CardNode } from "@/lib/cards/sandbox";
import type { ParamState } from "@/lib/cards/params";
import type { z } from "zod";
import type { linkTarget } from "@/lib/cards/tree";
import { CARD_HEIGHT, type CardSize } from "@/lib/cards/sizes";
import { CardChart, type CardChartProps } from "./card-chart";

type Live = { params: ParamState[]; setParam: (name: string, value: string) => void; busy: boolean };
const LiveCard = createContext<Live>({ params: [], setParam: () => {}, busy: false });

const PAGES: Record<z.infer<typeof linkTarget>["page"], string> = { transactions: "/money/transactions", budgets: "/plan/spending", recurring: "/money/recurring",
  goals: "/plan", accounts: "/money/accounts", wealth: "/money/wealth", plan: "/plan", forecast: "/plan", artifacts: "/ai/artifacts" };
/** Links are built by the app from a typed target; a card never supplies a URL. */
export function linkHref({ page, ...filters }: z.infer<typeof linkTarget>) {
  const query = new URLSearchParams(Object.entries(filters).filter((entry): entry is [string, string] => typeof entry[1] === "string"));
  return `${PAGES[page]}${page === "transactions" && query.size ? `?${query}` : ""}`;
}

function Money({ minor, currency, signed, compact, className, style }: { minor: string | number; currency: string; signed?: boolean; compact?: boolean; className?: string; style?: React.CSSProperties }) {
  const value = BigInt(minor);
  let text: string;
  try {
    text = compact ? new Intl.NumberFormat(undefined, { style: "currency", currency, notation: "compact", maximumFractionDigits: 1 }).format(Number(value) / 10 ** (new Intl.NumberFormat("en", { style: "currency", currency }).resolvedOptions().maximumFractionDigits ?? 2))
      : formatMoney(value, currency);
  } catch { text = `${value} ${currency}`; }
  return <span className={`tabular-nums ${className ?? ""}`} style={style}>{signed && value > 0n ? "+" : ""}{text}</span>;
}

function Tabs({ tabs, className, style, scope }: { tabs: { label: string; content: CardNode }[]; className?: string; style?: React.CSSProperties; scope: string }) {
  const [open, setOpen] = useState(0);
  return <div className={className} style={style}>
    <div role="tablist" className="mb-2 inline-flex rounded-lg border border-border p-0.5">{tabs.map((tab, index) => <button key={tab.label} type="button" role="tab" aria-selected={open === index}
      onClick={() => setOpen(index)} className="rounded-md px-2.5 py-1 text-xs text-muted-foreground aria-selected:bg-muted aria-selected:text-foreground">{tab.label}</button>)}</div>
    {/* Every panel is already rendered, so switching is instant. */}
    {tabs.map((tab, index) => <div key={tab.label} role="tabpanel" hidden={open !== index}>{render(tab.content, scope)}</div>)}
  </div>;
}

function Param({ name, variant, className, style }: { name: string; variant?: "pills" | "select"; className?: string; style?: React.CSSProperties }) {
  const { params, setParam, busy } = useContext(LiveCard);
  const param = params.find(item => item.name === name);
  if (!param) return null;
  if (variant === "select" || param.options.length > 5) return <select aria-label={name} value={param.value} disabled={busy} onChange={event => setParam(name, event.target.value)}
    className={`h-7 rounded-lg border border-border bg-card px-2 text-xs ${className ?? ""}`} style={style}>{param.options.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select>;
  return <div className={`inline-flex rounded-lg border border-border p-0.5 ${className ?? ""}`} style={style}>{param.options.map(option => <button key={option.value} type="button" aria-pressed={param.value === option.value}
    disabled={busy} onClick={() => setParam(name, option.value)} className="rounded-md px-2 py-0.5 font-mono text-[11px] text-muted-foreground aria-pressed:bg-muted aria-pressed:text-foreground">{option.label}</button>)}</div>;
}

/** Turns a checked tree into React elements; Kit names map to the components above. */
function render(node: CardNode, scope: string, key?: number): ReactNode {
  if (typeof node === "string") return node;
  const children = node.children.map((child, index) => render(child, scope, index));
  if (node.type === "#fragment") return <Fragment key={key}>{children}</Fragment>;
  const props = node.props as Record<string, never>;
  switch (node.type) {
    case "kit:Money": return <Money key={key} {...props} />;
    case "kit:Chart": return <CardChart key={key} {...(props as CardChartProps)} />;
    case "kit:Tabs": return <Tabs key={key} {...props} scope={scope} />;
    case "kit:Param": return <Param key={key} {...props} />;
    case "kit:Link": { const { to, ...rest } = node.props as { to: z.infer<typeof linkTarget> }; return <Link key={key} href={linkHref(to)} {...rest} className={`hover:underline ${(rest as { className?: string }).className ?? ""}`}>{children}</Link>; }
    case "kit:Style": return <style key={key}>{(node.props as { css: string }).css}</style>;
    default: return createElement(node.type, { key, ...props }, ...(children.length ? children : []));
  }
}

export type CardViewProps = { cardId: string; title: string; size: CardSize; tree: CardNode | null; error?: string | null; params: ParamState[]; scope: string; version?: number; open?: string };

/**
 * A Home card: the app's own title row, then the card's checked tree in a fixed-height, clipped, isolated box.
 * Nothing in the tree can paint outside the box or cover the rest of Home. Changing a param re-renders it on the server.
 */
export function CardView({ cardId, title, size, tree: initialTree, error: initialError, params: initialParams, scope, version, open }: CardViewProps) {
  const [view, setView] = useState({ tree: initialTree, error: initialError ?? null, params: initialParams });
  const [busy, start] = useTransition();
  const [seen, setSeen] = useState(initialTree);
  // A server re-render (a new version, another size) replaces what this card showed.
  if (seen !== initialTree) { setSeen(initialTree); setView({ tree: initialTree, error: initialError ?? null, params: initialParams }); }
  function setParam(name: string, value: string) {
    const query = new URLSearchParams({ size, ...(version ? { v: String(version) } : {}) });
    for (const param of view.params) query.set(`p.${param.name}`, param.name === name ? value : param.value);
    start(async () => {
      const response = await fetch(`/api/cards/${cardId}?${query}`, { cache: "no-store" });
      const body = await response.json().catch(() => ({ error: "Could not load the card" }));
      setView(current => response.ok ? { tree: body.tree, error: body.error ?? null, params: body.params } : { ...current, error: body.error ?? "Could not load the card" });
    });
  }
  return <section aria-label={title} className="flex flex-col overflow-hidden rounded-2xl border border-border bg-card" style={{ height: CARD_HEIGHT }}>
    <div className="flex items-baseline justify-between gap-2 px-5 pt-4 pb-2"><h2 className="truncate text-sm font-medium">{title}</h2>{open && <Link href={open} className="shrink-0 text-sm font-medium text-brand hover:underline">Open</Link>}</div>
    <div data-card={scope} className={`relative isolate min-h-0 flex-1 overflow-clip px-5 pb-4 transition-opacity [contain:layout_paint_style] ${busy ? "opacity-60" : ""}`}>
      <LiveCard.Provider value={{ params: view.params, setParam, busy }}>
        {view.tree ? render(view.tree, scope) : null}
      </LiveCard.Provider>
      {view.error && <p role="alert" className="text-sm text-muted-foreground">{view.error}</p>}
    </div>
  </section>;
}

import { z } from "zod";

/**
 * Six card shapes we wrote ourselves. The model picks one and fills its settings; values are paths into the
 * card's data (e.g. "month.spending_formatted" or "byCategory.rows"), so amounts always come from the app.
 * They render through the same pipeline as designed cards, from trusted source.
 */
const path = z.string().regex(/^[a-zA-Z_][\w]*(\.[\w]+)*$/).max(200);
const field = z.string().regex(/^[\w]+(\.[\w]+)*$/).max(100);
const tone = z.enum(["positive", "negative", "neutral"]).optional();
const text = z.string().max(120);

export const PRESETS = {
  stat: { description: "One big figure with a label and an optional note line, e.g. spent this month.",
    config: z.object({ label: text, value: path, note: path.optional(), noteText: text.optional(), tone }).strict() },
  stat_row: { description: "Two to four figures side by side, e.g. income / spending / net.",
    config: z.object({ items: z.array(z.object({ label: text, value: path, tone }).strict()).min(2).max(4) }).strict() },
  bar_list: { description: "A ranked list with a bar per row, e.g. spending by category or top merchants.",
    config: z.object({ rows: path, label: field, value: field, amount: field, limit: z.number().int().min(1).max(12).default(5), headline: path.optional() }).strict() },
  trend: { description: "A headline figure over a line, area or bar chart of a series, e.g. monthly spending.",
    config: z.object({ rows: path, label: field, amount: field, kind: z.enum(["line", "area", "bar"]).default("area"), headline: path.optional(), caption: text.optional(), currency: z.string().regex(/^[A-Z]{3}$/).optional() }).strict() },
  progress: { description: "Progress bars toward targets, e.g. savings goals or budgets.",
    config: z.object({ rows: path, label: field, current: field, target: field, note: field.optional(), limit: z.number().int().min(1).max(6).default(3) }).strict() },
  list: { description: "A compact list of items with a trailing value, e.g. upcoming bills or recent transactions.",
    config: z.object({ rows: path, primary: field, secondary: field.optional(), trailing: field, limit: z.number().int().min(1).max(8).default(4) }).strict() },
} as const;
export type PresetName = keyof typeof PRESETS;
export const PRESET_NAMES = Object.keys(PRESETS) as [PresetName, ...PresetName[]];
export const PRESET_GUIDE = PRESET_NAMES.map(name => `- ${name}: ${PRESETS[name].description}`).join("\n");

const HELPERS = `
const get = (from: any, path?: string) => path ? path.split(".").reduce((value, key) => value == null ? undefined : value[key], from) : undefined;
const show = (value: any) => value == null ? "–" : typeof value === "object" ? (value.formatted ?? value.valueFormatted ?? JSON.stringify(value)) : String(value);
const num = (value: any) => { const n = Number(value); return Number.isFinite(n) ? n : 0; };
const toneColor = (tone?: string) => tone === "positive" ? "var(--color-success)" : tone === "negative" ? "var(--color-danger)" : undefined;
const big = "font-display text-4xl font-semibold tracking-tight tabular-nums";
const rowsOf = (data: any, path: string) => { const rows = get(data, path); return Array.isArray(rows) ? rows : []; };
`;

const TEMPLATES: Record<PresetName, string> = {
  stat: `export default function Card({ data }) {
  return <div className="flex h-full flex-col justify-center gap-1">
    <p className="eyebrow">{config.label}</p>
    <p className={big} style={{ color: toneColor(config.tone) }}>{show(get(data, config.value))}</p>
    {(config.note || config.noteText) && <p className="text-sm text-muted-foreground">{config.note ? show(get(data, config.note)) : config.noteText}</p>}
  </div>;
}`,
  stat_row: `export default function Card({ data, size }) {
  return <div className="grid h-full content-center gap-4" style={{ gridTemplateColumns: \`repeat(\${size === "S" ? 1 : config.items.length}, minmax(0, 1fr))\` }}>
    {config.items.map(item => <div key={item.label} className="min-w-0">
      <p className="eyebrow">{item.label}</p>
      <p className="truncate text-2xl font-semibold tabular-nums" style={{ color: toneColor(item.tone) }}>{show(get(data, item.value))}</p>
    </div>)}
  </div>;
}`,
  bar_list: `export default function Card({ data, size }) {
  const rows = rowsOf(data, config.rows).slice(0, size === "S" ? Math.min(config.limit, 4) : config.limit);
  const max = Math.max(1, ...rows.map(row => Math.abs(num(get(row, config.amount)))));
  return <div className="flex h-full flex-col gap-2">
    {config.headline && <p className="text-2xl font-semibold tabular-nums">{show(get(data, config.headline))}</p>}
    {!rows.length && <p className="text-sm text-muted-foreground">Nothing to show yet.</p>}
    <ul className="space-y-2">{rows.map((row, index) => <li key={index}>
      <div className="flex justify-between gap-3 text-sm"><span className="truncate">{show(get(row, config.label))}</span><span className="shrink-0 font-mono text-xs">{show(get(row, config.value))}</span></div>
      <div className="mt-1 h-1.5 rounded-full bg-muted"><div className="h-full rounded-full bg-brand" style={{ width: (Math.abs(num(get(row, config.amount))) / max * 100) + "%" }} /></div>
    </li>)}</ul>
  </div>;
}`,
  trend: `export default function Card({ data }) {
  const rows = rowsOf(data, config.rows);
  return <div className="flex h-full flex-col justify-end gap-2">
    {config.headline && <p className="text-3xl font-semibold tabular-nums">{show(get(data, config.headline))}</p>}
    {config.caption && <p className="text-xs text-muted-foreground">{config.caption}</p>}
    {rows.length ? <Kit.Chart type={config.kind} height={config.headline ? 110 : 160} currency={config.currency} labels={rows.map(row => String(show(get(row, config.label))))} series={[{ name: config.caption ?? "Value", values: rows.map(row => num(get(row, config.amount))) }]} />
      : <p className="text-sm text-muted-foreground">Nothing to show yet.</p>}
  </div>;
}`,
  progress: `export default function Card({ data }) {
  const rows = rowsOf(data, config.rows).slice(0, config.limit);
  return <ul className="flex h-full flex-col justify-center gap-4">
    {!rows.length && <li className="text-sm text-muted-foreground">Nothing to show yet.</li>}
    {rows.map((row, index) => { const share = Math.min(100, Math.max(0, num(get(row, config.current)) / Math.max(1, num(get(row, config.target))) * 100)); return <li key={index}>
      <div className="flex justify-between gap-3 text-sm"><span className="truncate font-medium">{show(get(row, config.label))}</span><span className="shrink-0 font-mono text-xs">{Math.round(share)}%</span></div>
      <div className="mt-1.5 h-2 rounded-full bg-muted"><div className="h-full rounded-full bg-brand" style={{ width: share + "%" }} /></div>
      {config.note && <p className="mt-1 text-xs text-muted-foreground">{show(get(row, config.note))}</p>}
    </li>; })}
  </ul>;
}`,
  list: `export default function Card({ data, size }) {
  const rows = rowsOf(data, config.rows).slice(0, config.limit);
  return <ul className="divide-y divide-border">
    {!rows.length && <li className="py-2 text-sm text-muted-foreground">Nothing to show yet.</li>}
    {rows.map((row, index) => <li key={index} className="flex items-center justify-between gap-3 py-2">
      <span className="min-w-0"><span className="block truncate text-sm">{show(get(row, config.primary))}</span>{config.secondary && size !== "S" && <span className="block truncate text-xs text-muted-foreground">{show(get(row, config.secondary))}</span>}</span>
      <span className="shrink-0 font-mono text-xs">{show(get(row, config.trailing))}</span>
    </li>)}
  </ul>;
}`,
};

/** The card source for a preset: the settings, our helpers and the template. */
export function presetSource(preset: PresetName, config: unknown) {
  const parsed = PRESETS[preset].config.parse(config);
  return `const config = ${JSON.stringify(parsed)};\n${HELPERS}\n${TEMPLATES[preset]}\n`;
}

import { createHash } from "node:crypto";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { requireWorkspace } from "@/lib/auth";
import { calendarDate } from "@/lib/finance/calendar";
import { artifactQueriesSchema, checkQueries, runArtifactQueries, type ArtifactQuery, type QueryShared } from "@/lib/ai/artifact-data";
import { cardParamsSchema, resolveParams, type CardParam, type ParamState } from "./params";
import { compileCard, runCard, type CardNode } from "./sandbox";
import { CardTreeError, sanitizeTree } from "./tree";
import { CARD_SIZE_KEYS, isCardSize, type CardSize } from "./sizes";

type Context = Awaited<ReturnType<typeof requireWorkspace>>;
export type CardVersion = { id: string; card_id: string; version: number; kind: "preset" | "code"; preset: string | null; compiled: string; queries: unknown; params: unknown };
export type CardRow = { id: string; artifact_id: string; title: string; size: string; published_version: number | null };
export type RenderedCard = { tree: CardNode | null; error: string | null; params: ParamState[] };
export const CARD_VERSION_COLUMNS = "id, card_id, version, kind, preset, compiled, queries, params";

/** Each card's CSS and ids are namespaced by this, so two cards never clash. */
export const cardScope = (cardId: string) => `c${cardId.replace(/-/g, "").slice(0, 12)}`;

// Same card version, size, params and data give the same tree, so a repeat view skips the sandbox. The data is
// part of the key, so a cached tree is never older than the data it was made from; scopes are checked before.
const cache = new Map<string, CardNode>();
const CACHE_ENTRIES = 500;
const RENDERER_VERSION = 1;
function remember(key: string, tree: CardNode) {
  cache.delete(key);
  cache.set(key, tree);
  if (cache.size > CACHE_ENTRIES) cache.delete(cache.keys().next().value!);
}

function definition(version: Pick<CardVersion, "queries" | "params">) {
  return { queries: artifactQueriesSchema.parse(version.queries), params: cardParamsSchema.parse(version.params) };
}

/** Runs the card's queries for today, then its code in the sandbox, then checks the tree. Errors become a message, never a broken Home. */
export async function renderCard(version: CardVersion, context: Context, { size, requested = {}, shared }: { size: CardSize; requested?: Record<string, string | undefined>; shared?: QueryShared }): Promise<RenderedCard> {
  const today = calendarDate(new Date(), context.settings.timezone);
  let params: ParamState[] = [];
  try {
    const { queries, params: declared } = definition(version);
    const { resolved, state } = resolveParams(declared, requested, today, context.workspace.locale);
    params = state;
    const data = await runArtifactQueries(queries, context, today, { params: resolved, shared });
    const input = { data, params: resolved.values, size };
    const key = createHash("sha256").update(JSON.stringify([RENDERER_VERSION, context.workspace.id, version.id, input])).digest("base64url");
    const hit = cache.get(key);
    if (hit) return { tree: hit, error: null, params };
    const tree = sanitizeTree(await runCard(version.compiled, input), { scope: cardScope(version.card_id) });
    remember(key, tree);
    return { tree, error: null, params };
  } catch (cause) {
    return { tree: null, error: `This card could not be shown: ${cause instanceof Error ? cause.message : "unknown error"}`, params };
  }
}

/**
 * Checks a new card before it is saved: it compiles, its queries are valid, and it renders a clean tree at
 * every size with today's data. The errors go back to the designer to fix.
 */
export async function checkCard(source: string, queries: ArtifactQuery[], params: CardParam[], context: Context) {
  let compiled: string;
  try { compiled = compileCard(source); } catch (cause) { return { errors: [`Syntax: ${cause instanceof Error ? cause.message : String(cause)}`] }; }
  const today = calendarDate(new Date(), context.settings.timezone);
  const { resolved } = resolveParams(params, {}, today, context.workspace.locale);
  const queryErrors = checkQueries(queries, today, resolved);
  if (queryErrors.length) return { errors: queryErrors };
  const data = await runArtifactQueries(queries, context, today, { params: resolved });
  const errors: string[] = [];
  for (const size of CARD_SIZE_KEYS) {
    try { sanitizeTree(await runCard(compiled, { data, params: resolved.values, size }), { scope: "check" }); }
    catch (cause) { errors.push(`${size}: ${cause instanceof CardTreeError ? "" : "runtime "}${cause instanceof Error ? cause.message : String(cause)}`); }
  }
  return errors.length ? { errors } : { compiled, data };
}

/** The version a card shows: the one asked for (a draft preview), or the published one. */
export async function loadCardVersion(supabase: SupabaseClient, workspaceId: string, cardId: string, version?: number | null) {
  const query = supabase.from("artifact_card_versions").select(CARD_VERSION_COLUMNS).eq("workspace_id", workspaceId).eq("card_id", cardId);
  const { data, error } = await (version ? query.eq("version", version) : query.order("version", { ascending: false }).limit(1)).maybeSingle();
  if (error) throw error;
  return data as CardVersion | null;
}

export const cardSize = (value: string): CardSize => isCardSize(value) ? value : "M";

